<?php
declare(strict_types=1);

function renderRetentionCard(int $day,array $ret): void
{
    $value=$ret['state']==='measured'?number_format((float)$ret['percent'],1).'%':($ret['state']==='waiting'?'Waiting':'No cohort');
    $note=$ret['eligible']?number_format((int)$ret['returned']).' of '.number_format((int)$ret['eligible']).' returned':($ret['next']?'First complete result: '.$ret['next'].' UTC':'No measured new-player group in this range.');
    echo '<article class="stat-card retention-card accent-'.([1=>'lime',3=>'blue',7=>'pink',30=>'amber'][$day]).'"><span>D'.$day.' retention</span><strong class="'.($ret['eligible']?'':'metric-status').'">'.e($value).'</strong><small>'.e($note).'</small>';
    if($ret['pending'])echo '<span class="metric-caption">'.number_format((int)$ret['pending']).' players still in the observation window</span>';
    echo '</article>';
}
function renderAnalyticsToolbar(array $r,string $page,string $source,array $extra=[]): void
{
    ?><form class="analysis-toolbar" method="get"><input type="hidden" name="page" value="<?= e($page) ?>"><?php foreach($extra as $name=>$value): ?><input type="hidden" name="<?= e($name) ?>" value="<?= e($value) ?>"><?php endforeach; ?>
    <div class="field"><label for="analysis-period">Time range</label><select id="analysis-period" name="days" data-range-preset><?php foreach(['1'=>'Today','7'=>'7 days','30'=>'30 days','90'=>'90 days','180'=>'6 months','365'=>'1 year','730'=>'2 years','0'=>'All time','custom'=>'Custom dates'] as $value=>$label): ?><option value="<?= e($value) ?>" <?= $r['preset']===(string)$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></div>
    <div class="field date-field"><label for="analysis-start">From · UTC</label><input id="analysis-start" name="start" type="date" value="<?= e($r['start']) ?>" max="<?= gmdate('Y-m-d') ?>" data-range-date></div><div class="field date-field"><label for="analysis-end">To · UTC</label><input id="analysis-end" name="end" type="date" value="<?= e($r['end']) ?>" max="<?= gmdate('Y-m-d') ?>" data-range-date></div>
    <div class="field"><label for="analysis-server">Server</label><select id="analysis-server" name="server"><option value="">Network / all servers</option><?php foreach(obsServers() as $server): ?><option value="<?= e($server) ?>" <?= $server===$source?'selected':'' ?>><?= e(strtoupper($server)) ?></option><?php endforeach; ?></select></div>
    <div class="field"><label for="analysis-group">Resolution</label><select id="analysis-group" name="group"><?php foreach(['auto'=>'Automatic','hour'=>'Hourly','day'=>'Daily','week'=>'Weekly','month'=>'Monthly'] as $key=>$label): ?><option value="<?= $key ?>" <?= $r['requested_group']===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></div><button type="submit" class="button">Apply range</button></form>
    <div class="analysis-coverage"><span><i class="status-dot"></i><strong><?= e($r['start']) ?> — <?= e($r['end']) ?></strong> · <?= e(ucfirst($r['group'])) ?> groups · UTC<?= $r['partial']?' · Current day in progress':'' ?></span><span><?= $r['extent']['first']?'Statistics available since '.e(substr($r['extent']['first'],0,10)):'Waiting for the first statistics' ?></span></div>
    <?php if($r['error']): ?><div class="notice notice-info"><?= e($r['error']) ?></div><?php endif;
}

/** Bounded, accessible SVG. Gaps stay gaps; client legends, cursor, keyboard and zoom use the same data. */
function renderAnalyticsChart(array $series,array $range,array $options=[]): void
{
    $title=(string)($options['title']??'Time series');$description=(string)($options['description']??'');
    $labels=$series?array_keys($series[0]['values']):[];$any=false;$minimum=0.;$maximum=1.;
    foreach($series as $s)foreach($s['values'] as $n)if($n!==null&&is_finite((float)$n)){$any=true;$minimum=min($minimum,(float)$n);$maximum=max($maximum,(float)$n);}
    if(!$any){echo '<div class="chart-empty"><span class="empty-chart-icon">↗</span><strong>No measured values in this range</strong><p>Choose another period or wait for new data. Missing history is not shown as zero.</p></div>';return;}
    if(!empty($options['percent'])){$maximum=100.;$minimum=0.;}else{$scale=10**floor(log10(max(abs($maximum),abs($minimum),1)));$maximum=ceil($maximum/$scale*4)/4*$scale;$minimum=floor($minimum/$scale*4)/4*$scale;}
    $data=['labels'=>$labels,'series'=>[],'group'=>$options['group']??$range['group'],'from'=>$range['from'],'until'=>$range['until'],'percent'=>!empty($options['percent']),'title'=>$title,'cumulative'=>!empty($options['cumulative']),'categories'=>!empty($options['categories'])];
    foreach($series as $i=>$s)$data['series'][]=['key'=>$s['key']??(string)$i,'label'=>$s['label'],'color'=>$s['color']??'#69b6ff','unit'=>$s['unit']??'','values'=>array_values($s['values'])];
    $count=count($labels);$position=static fn($i,$n)=>[round(70+($count<2?450:$i/($count-1)*900),2),round(247-((float)$n-$minimum)/max(.00001,$maximum-$minimum)*215,2)];
    ?><div class="analysis-chart" data-analysis-chart data-chart-data="<?= e(jsonEncode($data)) ?>"><div class="chart-controls"><div class="chart-legend" aria-label="Show or hide series"><?php foreach($data['series'] as $i=>$s): ?><button type="button" class="legend-button" data-series-toggle="<?= $i ?>" aria-pressed="true"><i style="background:<?= e($s['color']) ?>"></i><?= e($s['label']) ?></button><?php endforeach; ?></div><div class="chart-tools"><?php if(!empty($options['cumulative'])): ?><button class="chart-tool" type="button" data-chart-cumulative aria-pressed="false">Cumulative</button><?php endif; ?><button type="button" class="chart-tool" data-chart-reset hidden>Reset zoom</button></div></div>
    <div class="chart-surface"><svg viewBox="0 0 1000 300" tabindex="0" role="img" aria-label="<?= e($title) ?>. Hover for values, use arrow keys, or drag to zoom.">
    <?php for($i=0;$i<=4;$i++):$y=32+$i/4*215; ?><g data-y-tick="<?= $i ?>"><line class="chart-grid-line" x1="70" y1="<?= $y ?>" x2="970" y2="<?= $y ?>"></line><text class="chart-axis-label" x="58" y="<?= $y+4 ?>" text-anchor="end"><?= e(obsNumber($maximum-$i/4*($maximum-$minimum))) ?></text></g><?php endfor; ?>
    <g data-x-ticks><?php for($t=0;$t<min(6,$count);$t++):$i=(int)round($t/max(1,min(6,$count)-1)*($count-1));[$x]=$position($i,0);$stamp=strtotime($labels[$i].' UTC');$text=!empty($data['categories'])?$labels[$i]:gmdate($data['group']==='hour'?'M j H:i':($data['group']==='month'?'M Y':'M j, Y'),$stamp); ?><text class="chart-axis-label" x="<?= $x ?>" y="279" text-anchor="middle"><?= e($text) ?></text><?php endfor; ?></g>
    <?php foreach($data['series'] as $i=>$s):$path='';$start=true;foreach($s['values'] as $j=>$n){if($n===null){$start=true;continue;}[$x,$y]=$position($j,$n);$path.=($start?'M':'L').$x.','.$y.' ';$start=false;} ?><g data-series-line="<?= $i ?>"><path class="chart-line" fill="none" d="<?= e($path) ?>" style="stroke:<?= e($s['color']) ?>"></path><g data-series-dots><?php if($count<=80):foreach($s['values'] as $j=>$n):if($n===null)continue;[$x,$y]=$position($j,$n); ?><circle cx="<?= $x ?>" cy="<?= $y ?>" r="2.5" style="fill:<?= e($s['color']) ?>"></circle><?php endforeach;endif; ?></g></g><?php endforeach; ?>
    <rect data-chart-brush x="70" y="32" width="0" height="215" hidden></rect><line data-analysis-cursor x1="70" x2="70" y1="32" y2="247" hidden></line><g data-analysis-markers></g></svg><output class="analysis-tooltip" aria-live="polite" hidden></output></div>
    <div class="chart-caption"><span><?= e($description?:'Hover or tap for exact values. Drag across the graph to zoom.') ?></span><span data-zoom-label>Missing measurements appear as gaps.</span></div>
    <details class="chart-data"><summary>View exact values</summary><div class="table-wrap"><table><thead><tr><th>Bucket start · UTC</th><?php foreach($data['series'] as $s): ?><th><?= e($s['label']) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($labels as $i=>$date): ?><tr><td><?= e($date) ?></td><?php foreach($data['series'] as $s): ?><td><?= $s['values'][$i]===null?'No measurement':e(obsNumber((float)$s['values'][$i]).($s['unit']?' '.$s['unit']:'')) ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div></details></div><?php
}
function analyticsChartPanel(string $title,string $subtitle,array $series,array $r,array $options=[]): void
{
    echo '<article class="panel chart-panel"><div class="panel-header"><div><h2>'.e($title).'</h2><span class="cell-sub">'.e($subtitle).'</span></div><span class="badge">'.e(ucfirst($options['group']??$r['group'])).' · UTC</span></div><div class="panel-body">';renderAnalyticsChart($series,$r,[...$options,'title'=>$title]);echo '</div></article>';
}
function analyticsTablePanel(string $title,array $rows,string $unit='',string $note='',bool $shares=true): void
{
    echo '<article class="panel compact-table-panel"><div class="panel-header"><div><h2>'.e($title).'</h2>'.($note?'<span class="cell-sub">'.e($note).'</span>':'').'</div></div><div class="panel-body flush"><div class="table-wrap"><table><thead><tr><th>Category</th><th class="number-cell">'.($unit==='$'?'Value':'Count').'</th><th class="number-cell">'.($shares?'Share':'').'</th></tr></thead><tbody>';
    $total=array_sum(array_column($rows,'total'));foreach($rows as $row)echo '<tr><td>'.e(str_replace('|',' · ',(string)($row['label']?:'All'))).'</td><td class="number-cell">'.($unit==='$'?'$':'').e(obsNumber((float)$row['total'])).'</td><td class="number-cell muted">'.($shares?number_format(percent((float)$row['total'],(float)$total),1).'%':'—').'</td></tr>';
    if(!$rows)echo '<tr><td colspan="3"><div class="empty-state compact"><strong>No recorded data</strong></div></td></tr>';echo '</tbody></table></div></div></article>';
}
function analyticsKpi(string $label,float|int|null $value,string $note,string $accent='blue',string $unit='',?float $previous=null): void
{
    echo '<article class="stat-card accent-'.e($accent).'"><span>'.e($label).'</span><strong>'.($value===null?'—':($unit==='$'?'$':'').obsNumber($value).($unit&&$unit!=='$'?' '.$unit:'')).'</strong><small>'.e($note).'</small>';
    if($previous!==null&&$value!==null){$delta=$value-$previous;$relative=$previous>0?number_format(abs($delta/$previous*100),1).'%':obsNumber(abs($delta));echo '<span class="metric-comparison">'.($delta>0?'↑ ':($delta<0?'↓ ':'→ ')).e($relative).' vs previous matching period</span>';}
    echo '</article>';
}
function analyticsRetainedExplanation(): void
{
    echo '<div class="analysis-note"><strong>What retention measures</strong><p>D1 / D3 / D7 / D30 is the share of new players observed online on that exact UTC day after their first visit. A result becomes final after that entire day has ended. Staying online across midnight counts; a later last-seen date alone does not.</p></div>';
}

