    try { ?>
    <div class="analysis-heading"><div><span class="eyebrow">TOWNY REBORN · ANALYTICS</span><h2><?= e($tabs[$tab]) ?></h2><p>Explore the history. Inspect exact values. Keep permanent statistics beyond the 30-day player log.</p></div><a class="button secondary" href="index.php?<?= e(http_build_query(analyticsQuery($r,['page'=>'statistics','server'=>$source,'section'=>'All']))) ?>">Explore plugin metrics</a></div>
    <nav class="analysis-tabs" aria-label="Analytics sections"><?php foreach($tabs as $key=>$label): ?><a class="<?= $key===$tab?'active':'' ?>" href="index.php?<?= e(http_build_query(analyticsQuery($r,['page'=>'analytics','view'=>$key,'server'=>$source]))) ?>"><?= e($label) ?></a><?php endforeach; ?></nav>
    <?php renderAnalyticsToolbar($r,'analytics',$source,['view'=>$tab]);
    if($tab==='overview') {
        $daily=analyticsDailySeries($r,$source);$p=[$r['start'],$r['end'],$source?:'network'];$a=analyticsRows('SELECT AVG(active_players) mean,MAX(active_players) peak,SUM(new_players) newcomers FROM daily_server_stats WHERE day_utc>=? AND day_utc<=? AND server_name=?',$p)[0];
        $new=$source===''?statScalar('SELECT SUM(new_players) FROM retention_cohorts WHERE day_utc>=? AND day_utc<=?',[$r['start'],$r['end']]):null;
        echo '<section class="stats-grid analysis-kpis">';analyticsKpi('Players online now',obsOnline(),'Live network count','lime');analyticsKpi('Average daily active',(isset($a['mean'])?(float)$a['mean']:null),'Daily uniques · recorded days','blue');analyticsKpi('Peak daily active',isset($a['peak'])?(int)$a['peak']:null,'Busiest recorded UTC day','pink');analyticsKpi('New players',$new,$source===''?'First visit in selected range':'New-player cohorts are network-wide','amber');echo '</section>';
        analyticsChartPanel('Daily player activity','Unique active players; larger buckets show averages per recorded day.',$daily,$r,['group'=>$r['group']==='hour'?'day':$r['group']]);
        echo '<section class="analysis-two-col">';analyticsChartPanel('Recorded joins','Server connections include transfers between SMP, Hub and proxy.',analyticsMetricSeries($r,$source,['player_joins'],'',true),$r,['cumulative'=>true]);analyticsChartPanel('Chat volume','Message counts; message content remains in the 30-day log.',analyticsMetricSeries($r,$source,['messages'],'',true),$r,['cumulative'=>true]);echo '</section>';
        $ret=analyticsRetention($r)['summary'];echo '<div class="analysis-section-heading"><h2>Player retention</h2><a href="index.php?'.e(http_build_query(analyticsQuery($r,['page'=>'analytics','view'=>'retention']))).'">View cohort history →</a></div><section class="stats-grid retention-cards">';foreach([1,3,7,30] as $d)renderRetentionCard($d,$ret[$d]);echo '</section>';
        if($source!=='')echo '<p class="field-hint">Retention covers the whole network, including players moving between SMP and Hub.</p>';
        echo '<div class="analysis-note"><strong>Reading the timeline</strong><p>Statistics are anonymous and permanent. A gap means no measurement was recorded. Counts can be zero when the connector was observed in that bucket but no matching event occurred. The current day is still in progress.</p></div>';
    } elseif($tab==='retention') {
        $ret=analyticsRetention($r);echo '<div class="analysis-section-heading"><h2>Network retention</h2><a class="button secondary small" href="index.php?'.e(http_build_query(analyticsQuery($r,['page'=>'retention-export']))).'">Export cohorts</a></div><section class="stats-grid retention-cards">';foreach([1,3,7,30] as $d)renderRetentionCard($d,$ret['summary'][$d]);echo '</section>';analyticsRetainedExplanation();
        analyticsChartPanel('Retention by first-visit date','Only completed observation windows. Weekly and monthly rates are weighted by cohort size.',analyticsRetentionSeries($r,$ret['cohorts']),$r,['percent'=>true,'group'=>$r['group']==='hour'?'day':$r['group']]);
        $cohorts=array_reverse($ret['cohorts']);$total=count($cohorts);$offset=max(0,(int)($_GET['cohort_page']??1)-1)*60;$rows=array_slice($cohorts,$offset,60);
        ?><article class="panel"><div class="panel-header"><div><h2>New-player cohorts</h2><span class="cell-sub">Rows group players by their first visit date. Pending days never become a false 0%.</span></div><span class="badge"><?= $total ?> groups</span></div><div class="panel-body flush"><div class="table-wrap"><table class="cohort-table"><thead><tr><th>First visit · UTC</th><th>New players</th><?php foreach([1,3,7,30] as $d): ?><th>D<?= $d ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($rows as $c): ?><tr><td><?= e($c['day_utc']) ?></td><td><?= number_format((int)$c['new_players']) ?></td><?php foreach([1,3,7,30] as $d):$ready=gmdate('Y-m-d',strtotime($c['day_utc'].' UTC')+($d+1)*86400);$mature=$ready<=gmdate('Y-m-d');$pct=percent(min((int)$c['new_players'],(int)$c['d'.$d]),(int)$c['new_players']); ?><td class="<?= $mature?'cohort-result':'cohort-pending' ?>" style="<?= $mature?'background:rgba(101,222,154,'.(.025+$pct/100*.17).')':'' ?>"><?php if($mature): ?><strong><?= number_format($pct,1) ?>%</strong><small><?= (int)$c['d'.$d] ?> / <?= (int)$c['new_players'] ?></small><?php else: ?><span>Waiting</span><small><?= e($ready) ?></small><?php endif; ?></td><?php endforeach; ?></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="6"><div class="empty-state"><strong>No observed new-player cohorts</strong><p>Choose a range containing new players.</p></div></td></tr><?php endif; ?></tbody></table></div></div><?php if($total>60): ?><div class="analysis-pagination"><?php if($offset>0): ?><a href="index.php?<?= e(http_build_query(analyticsQuery($r,['page'=>'analytics','view'=>'retention','cohort_page'=>$offset/60]))) ?>">← Newer groups</a><?php endif; ?><span>Groups <?= min($total,$offset+1) ?>–<?= min($total,$offset+60) ?> of <?= $total ?></span><?php if($offset+60<$total): ?><a href="index.php?<?= e(http_build_query(analyticsQuery($r,['page'=>'analytics','view'=>'retention','cohort_page'=>$offset/60+2]))) ?>">Older groups →</a><?php endif; ?></div><?php endif; ?></article><?php
