        echo '<details class="analysis-details"><summary>Current workflow and retained alert details</summary><p class="field-hint">Alert status and severity use only the retained 30-day detail. Cases are permanent and network-wide.</p><section class="analysis-two-col">';$params=[$from,$until];$where='occurred_at>=? AND occurred_at<?'.analyticsScope('server_name',$source,$params);analyticsTablePanel('Alert severity',analyticsRows("SELECT severity label,COUNT(*) total FROM alerts WHERE $where GROUP BY severity ORDER BY total DESC",$params));analyticsTablePanel('Alert workflow',analyticsRows("SELECT status label,COUNT(*) total FROM alerts WHERE $where GROUP BY status ORDER BY total DESC",$params));analyticsTablePanel('Case status now',analyticsRows('SELECT status label,COUNT(*) total FROM cases GROUP BY status ORDER BY total DESC'));analyticsTablePanel('Case priority now',analyticsRows('SELECT priority label,COUNT(*) total FROM cases GROUP BY priority ORDER BY total DESC'));echo '</section></details>';
    } elseif($tab==='economy') {
        $snapshot=analyticsRows('SELECT SUM(balance) total,AVG(balance) mean,COUNT(balance) players FROM players WHERE last_seen_at>=DATE_SUB(NOW(),INTERVAL 30 DAY)')[0];
        echo '<section class="stats-grid analysis-kpis">';analyticsKpi('Jobs money paid',analyticsCounterTotal($r,$source,'money_paid'),'Tracked Jobs payments in this range','lime','$');analyticsKpi('Shop trade value',analyticsCounterTotal($r,$source,'trade_value'),'Recorded QuickShop transactions','blue','$');analyticsKpi('Tracked balance now',isset($snapshot['total'])?(float)$snapshot['total']:null,$snapshot['players'].' recently seen players · snapshot','pink','$');analyticsKpi('Average balance now',isset($snapshot['mean'])?(float)$snapshot['mean']:null,'Current recorded balances · snapshot','amber','$');echo '</section>';
        analyticsChartPanel('Jobs income','Money paid in each bucket; historical totals remain.',analyticsMetricSeries($r,$source,['money_paid'],'Jobs',true),$r,['cumulative'=>true]);
