        if(can('audit.view')) { $staff=analyticsStaffRows($r,$source); ?>
        <article class="panel"><div class="panel-header"><div><h2>Staff activity</h2><span class="cell-sub">Active HQ staff accounts and their linked Minecraft accounts only. Regular player commands are excluded.</span></div><span class="badge">Retained audit detail</span></div><div class="panel-body flush"><div class="table-wrap"><table data-staff-activity><thead><tr><th>Staff member</th><th>Role</th><th class="number-cell">Actions</th><th class="number-cell">Commands</th><th class="number-cell">Website actions</th></tr></thead><tbody><?php foreach($staff as $s): ?><tr data-staff-user="<?= (int)$s['id'] ?>"><td><?= linkedStaffIdentity($s) ?></td><td><?= e(ucfirst($s['role'])) ?></td><td class="number-cell"><?= number_format((int)$s['total']) ?></td><td class="number-cell"><?= number_format((int)$s['commands']) ?></td><td class="number-cell"><?= number_format((int)$s['portal_actions']) ?></td></tr><?php endforeach; ?><?php if(!$staff): ?><tr><td colspan="5"><div class="empty-state compact"><strong>No linked staff actions in this range</strong><p>Link Minecraft accounts in Staff Team.</p></div></td></tr><?php endif; ?></tbody></table></div></div></article><?php }
        echo '<details class="analysis-details"><summary>Player playtime distribution · current snapshot</summary>';analyticsTablePanel('Recorded playtime',analyticsRows("SELECT CASE WHEN playtime_seconds<3600 THEN 'Under 1 hour' WHEN playtime_seconds<36000 THEN '1–10 hours' WHEN playtime_seconds<180000 THEN '10–50 hours' WHEN playtime_seconds<360000 THEN '50–100 hours' ELSE '100+ hours' END label,COUNT(*) total FROM players GROUP BY label ORDER BY MIN(playtime_seconds)"));echo '</details>';
    } elseif($tab==='performance') {
        analyticsChartPanel('Players online','Measured averages by server. These are concurrent players, not unique visitors.',analyticsMetricSeries($r,$source,['online_players'],'Server',true),$r);
        echo '<section class="analysis-two-col">';analyticsChartPanel('TPS','Weighted average of samples per bucket; absent samples remain gaps.',analyticsMetricSeries($r,$source,['tps'],'Server',true),$r);analyticsChartPanel('MSPT','Milliseconds per server tick; separate from TPS.',analyticsMetricSeries($r,$source,['mspt'],'Server',true),$r);echo '</section>';
        analyticsChartPanel('Memory used','Measured server memory in MB.',analyticsMetricSeries($r,$source,['memory_used_mb'],'Server',true),$r);
        echo '<section class="analysis-two-col">';analyticsChartPanel('Warnings','New collected server WARN headers.',analyticsMetricSeries($r,$source,['log_warn'],'',true),$r,['cumulative'=>true]);analyticsChartPanel('Errors','New collected server ERROR headers.',analyticsMetricSeries($r,$source,['log_error'],'',true),$r,['cumulative'=>true]);echo '</section><div class="button-row"><a class="button secondary" href="index.php?page=plugins">Plugin health & updates</a><a class="button secondary" href="index.php?page=diagnostics">Inspect diagnostics</a></div>';
    }
        $content=(string)ob_get_clean();
    } catch(Throwable $error) {
        while(ob_get_level()>$bufferLevel)ob_end_clean();
        error_log('[TR Staff HQ] Analytics render failed ('.get_class($error).'): '.$error->getMessage());
        http_response_code(500);
        renderErrorPage('Analytics temporarily unavailable','Please reload this page. If the problem continues, contact the HQ administrator.');
        return;
    }
    renderAppPage('Analytics','analytics',$content);
}

function analyticsStatisticsSections(): array
{
    return ['Gameplay'=>['Minecraft','PyroFishingPro','mcMMO','Quests','ExcellentCrates','ArtMap','GSit','PinataParty','Citizens','MythicMobs'],'Economy'=>['Jobs','AxAuctions','QuickShop-Hikari','Votifier'],'World & Towny'=>['Towny'],'Moderation'=>['Vulcan','LiteBans','Staff','Chat review'],'Performance'=>['Server'],'All'=>[]];
}
function analyticsStatisticsFilter(array $r,bool $includeMetric=true): array
{
    $source=obsText($_GET['server']??'',64);$plugin=obsText($_GET['plugin']??'',96);$section=(string)($_GET['section']??'Gameplay');$sections=analyticsStatisticsSections();if(!isset($sections[$section]))$section='Gameplay';$params=[$r['from'],$r['until']];$where='hour_utc>=? AND hour_utc<?'.analyticsScope('server_name',$source,$params);if($plugin!==''){$where.=' AND plugin_name=?';$params[]=$plugin;}
    if($sections[$section]){$where.=' AND plugin_name IN('.implode(',',array_fill(0,count($sections[$section]),'?')).')';array_push($params,...$sections[$section]);}
    if($includeMetric&&!empty($_GET['metric'])){$where.=' AND metric=?';$params[]=obsText($_GET['metric'],64);}
    if(!empty($_GET['dimension'])){$where.=' AND dimension=?';$params[]=obsText($_GET['dimension'],128);}
    return [$source,$plugin,$section,$where,$params];
}
function showStatisticsWorkspace(): void
{
    requirePermission('analytics.view');$r=analyticsRange();[$source,$plugin,$section,$where,$params]=analyticsStatisticsFilter($r,false);$sections=analyticsStatisticsSections();$metric=obsText($_GET['metric']??'',64);
    $metrics=analyticsRows('SELECT plugin_name,metric,SUM(value_sum) total,SUM(sample_count) samples,MIN(value_min) lowest,MAX(value_max) peak FROM metric_hourly WHERE '.$where.' GROUP BY plugin_name,metric ORDER BY plugin_name,metric',$params);$choices=array_values(array_unique(array_column($metrics,'metric')));if(!in_array($metric,$choices,true))$metric=in_array('mob_kills',$choices,true)?'mob_kills':($choices[0]??'');
    $dimension=obsText($_GET['dimension']??'',128);$gauge=analyticsGauge($metric);$selected=array_values(array_filter($metrics,fn($m)=>$m['metric']===$metric));
    $dimensions=analyticsRows('SELECT dimension label,'.($gauge?'SUM(value_sum)/NULLIF(SUM(sample_count),0)':'SUM(value_sum)').' total FROM metric_hourly WHERE '.$where.' AND metric=? GROUP BY dimension ORDER BY total DESC LIMIT 40',[...$params,$metric]);
    $plugins=db()->query('SELECT DISTINCT plugin_name FROM metric_hourly ORDER BY plugin_name')->fetchAll(PDO::FETCH_COLUMN);
    ob_start();gameSubnav('statistics'); ?><div class="analysis-heading"><div><span class="eyebrow">TOWNY REBORN · METRICS EXPLORER</span><h2><?= e(obsMetricLabel($metric)?:'Game statistics') ?></h2><p>Permanent totals with hourly, daily, weekly and monthly history. Search individual plugin metrics.</p></div><a class="button secondary" href="index.php?<?= e(http_build_query(analyticsQuery($r,['page'=>'stats-export','section'=>$section,'server'=>$source,'plugin'=>$plugin,'metric'=>$metric,'dimension'=>$dimension]))) ?>">Export selected data</a></div>
    <nav class="analysis-tabs" aria-label="Statistics categories"><?php foreach($sections as $name=>$unused): ?><a class="<?= $section===$name?'active':'' ?>" href="index.php?<?= e(http_build_query(analyticsQuery($r,['page'=>'statistics','section'=>$name,'server'=>$source]))) ?>"><?= e($name) ?></a><?php endforeach; ?></nav>
    <?php renderAnalyticsToolbar($r,'statistics',$source,['section'=>$section,'plugin'=>$plugin,'metric'=>$metric,'dimension'=>$dimension]); ?>
    <form class="metric-selector" method="get"><input type="hidden" name="page" value="statistics"><?php foreach(analyticsQuery($r,['server'=>$source,'section'=>$section]) as $k=>$v): ?><input type="hidden" name="<?= e($k) ?>" value="<?= e($v) ?>"><?php endforeach; ?><div class="field"><label for="metric-plugin">Plugin</label><select id="metric-plugin" name="plugin"><option value="">All in category</option><?php foreach($plugins as $p): ?><option <?= $plugin===$p?'selected':'' ?> value="<?= e($p) ?>"><?= e($p) ?></option><?php endforeach; ?></select></div><div class="field"><label for="metric-choice">Metric</label><select id="metric-choice" name="metric"><?php foreach($choices as $m): ?><option <?= $metric===$m?'selected':'' ?> value="<?= e($m) ?>"><?= e(obsMetricLabel($m)) ?></option><?php endforeach; ?></select></div><div class="field"><label for="metric-dimension">Type / origin</label><input id="metric-dimension" name="dimension" value="<?= e($dimension) ?>" placeholder="All types" list="metric-dimensions"><datalist id="metric-dimensions"><?php foreach($dimensions as $d): ?><option value="<?= e($d['label']) ?>"><?php endforeach; ?></datalist></div><button class="button secondary" type="submit">Select metric</button></form>
    <section class="stats-grid analysis-kpis"><?php foreach(array_slice($selected,0,4) as $m):analyticsKpi($m['plugin_name'].' · '.($gauge?'Average':'Total'),$gauge?(float)$m['total']/max(1,(int)$m['samples']):(float)$m['total'],obsNumber((int)$m['samples']).' observations','lime',analyticsMetricUnit($metric));endforeach; ?></section>
    <?php analyticsChartPanel(obsMetricLabel($metric)?:'Waiting for measurements',$gauge?'Weighted sample averages by server.':'Event totals per bucket, separated by server.',analyticsMetricSeries($r,$source,[$metric],$plugin,true,$dimension),$r,['cumulative'=>!$gauge]); ?>
    <?php if($metric==='mob_kills'): ?><div class="analysis-note"><strong>Mob origins</strong><p>Kill counts are credited to players. Spawn origins start being tracked after installation; previously spawned mobs may appear as UNKNOWN.</p></div><?php endif; ?>
    <section class="analysis-two-col"><?php analyticsTablePanel('Type / origin breakdown',$dimensions,analyticsMetricUnit($metric),$gauge?'Averages per type; percentage shares are not applicable.':'Recorded totals for the selected range',!$gauge); ?>
    <?php if(can('activity.view')&&$metric!=='') {
        [$from,$until]=analyticsLocalBounds($r);$from=max($from,date('Y-m-d H:i:s',time()-30*86400));$p=[$metric,$from,$until];$scope=analyticsScope('server_name',$source,$p);if($plugin!==''){$scope.=' AND plugin_name=?';$p[]=$plugin;}if($dimension!==''){$scope.=' AND dimension=?';$p[]=$dimension;}if($sections[$section]){$scope.=' AND plugin_name IN('.implode(',',array_fill(0,count($sections[$section]),'?')).')';array_push($p,...$sections[$section]);}
        $leaders=analyticsRows('SELECT player_uuid,MAX(player_name) player_name,SUM(value_sum) total FROM gameplay_activity WHERE metric=? AND last_at>=? AND last_at<?'.$scope.' GROUP BY player_uuid ORDER BY total DESC LIMIT 12',$p);
        ?><article class="panel"><div class="panel-header"><div><h2>Players in this range</h2><span class="cell-sub">Individual activity is available for the last 30 days only.</span></div><a class="button secondary small" href="index.php?page=activity&metric=<?= e($metric) ?>&server=<?= e($source) ?>">Inspect activity</a></div><div class="panel-body flush"><div class="table-wrap"><table><thead><tr><th>Player</th><th class="number-cell">Recorded total</th></tr></thead><tbody><?php foreach($leaders as $row): ?><tr><td><?= renderPlayerIdentity($row['player_name'],$row['player_uuid'],null,true) ?></td><td class="number-cell"><?= obsNumber((float)$row['total']) ?></td></tr><?php endforeach; ?><?php if(!$leaders): ?><tr><td colspan="2"><div class="empty-state compact"><strong>No retained player activity in this range</strong></div></td></tr><?php endif; ?></tbody></table></div></div></article><?php } ?></section>
    <article class="panel"><div class="panel-header"><div><h2>Recorded metrics</h2><span class="cell-sub">Choose a row to inspect that plugin and metric.</span></div><input class="table-search" type="search" placeholder="Find a metric…" aria-label="Search recorded metrics" data-table-search="recorded-metrics"></div><div class="panel-body flush"><div class="table-wrap"><table id="recorded-metrics"><thead><tr><th>Plugin</th><th>Metric</th><th class="number-cell">Total / mean</th><th class="number-cell">Samples</th><th class="number-cell">Peak observation</th></tr></thead><tbody><?php foreach($metrics as $m):$g=analyticsGauge($m['metric']); ?><tr><td><?= e($m['plugin_name']) ?></td><td><a href="index.php?<?= e(http_build_query(analyticsQuery($r,['page'=>'statistics','section'=>$section,'server'=>$source,'plugin'=>$m['plugin_name'],'metric'=>$m['metric']]))) ?>"><?= e(obsMetricLabel($m['metric'])) ?></a></td><td class="number-cell"><?= obsNumber($g?(float)$m['total']/max(1,(int)$m['samples']):(float)$m['total']) ?><?= $g?' mean':'' ?></td><td class="number-cell"><?= obsNumber((int)$m['samples']) ?></td><td class="number-cell"><?= obsNumber((float)$m['peak']) ?></td></tr><?php endforeach; ?><?php if(!$metrics): ?><tr><td colspan="5"><div class="empty-state"><strong>No metrics in this selection</strong><p>Try all categories, another plugin, or a longer period.</p></div></td></tr><?php endif; ?></tbody></table></div></div></article><?php
    renderAppPage('Game Statistics','statistics',(string)ob_get_clean());
}
function exportRetentionCohorts(): never
{
    requirePermission('analytics.view');$ret=analyticsRetention(analyticsRange());header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="townyreborn-retention.csv"');$out=fopen('php://output','w');fputcsv($out,['First visit UTC','New players','D1 returned','D1 eligible','D3 returned','D3 eligible','D7 returned','D7 eligible','D30 returned','D30 eligible']);foreach($ret['cohorts'] as $c){$row=[$c['day_utc'],$c['new_players']];foreach([1,3,7,30] as $d){$mature=gmdate('Y-m-d',strtotime($c['day_utc'].' UTC')+($d+1)*86400)<=gmdate('Y-m-d');$row[]=$mature?$c['d'.$d]:'';$row[]=$mature?$c['new_players']:'';}fputcsv($out,$row);}fclose($out);exit;
}
